            0.0
        };

        println!(
            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
            "mean min-p99",
            "",
            fmt_commas_f64(conv_f(trim_mean), 0),
        );
        println!(
            "{INDENT}{:<label_w$} {:>skip$}{GAP}{:>mean_w$} {unit}",
            "stdev min-p99",
            "",
            fmt_commas_f64(conv_f(trim_stdev), 0),
        );
    }
    println!();
}

